    id: USER_ID, email: 'ks732@example.test', first_name: 'K', last_name: 'S',
    display_name: 'KS', role: 'user', status: 'active', email_verified: true,
    password_hash: state.hasPassword ? '$2b$10$ks732fakehashfakehashfakehashfakehash' : null,
    phone_number: null, phone_verified: false,
    mfa_enabled: true, mfa_secret: 'JBSWY3DPEHPK3PXP',
    mfa_backup_codes: ['hashedcode1', 'hashedcode2'],
    verification_level: 'advanced', organization_id: null, tenant_id: null, tenant_slug: null,
    wallet_address: state.hasPassword ? null : 'addr_test1qks732wallet',
    auth_method: state.hasPassword ? 'password' : 'wallet',
    external_provider: null, external_id: null, google_id: null, linkedin_id: null,
