/**
 * PROJECT THE ROW ONTO THE COLUMNS THE SQL ACTUALLY ASKED FOR.
 *
 * #872 review, Peter's blocker: the previous stub returned the WHOLE row for any
 * `FROM users` query whatever the column list, so `getUserById`'s
 * `SELECT ${USER_COLS}` — which deliberately OMITS password_hash — still handed
 * the handler a password_hash the real SQL never requests. Every cell that
 * depends on the password branch was satisfied by a column production does not
 * select. The mock could not fail in the direction the defect lives, so its
 * green was not evidence.
 *
 * With projection the real SQL becomes load-bearing: change the column list and
 * the cells move.
 */
function projectToSelectedColumns(sql: string, row: Record<string, unknown>) {
  const m = /^\s*SELECT\s+([\s\S]+?)\s+FROM\s+/i.exec(sql);
  if (!m) return row;
  const list = m[1].trim();
  if (list === '*') return row;                      // SELECT * really does get everything
  const wanted = list.split(',').map(c => c.trim().split(/\s+as\s+/i).pop()!.trim());
  const out: Record<string, unknown> = {};
  for (const c of wanted) if (c in row) out[c] = row[c];
  return out;
}

vi.mock('../db', () => ({
