    if (/^\s*UPDATE\s+users/i.test(sql)) return { rows: [userRow()], rowCount: 1 };
    if (/FROM\s+users/i.test(sql)) {
      return { rows: [projectToSelectedColumns(sql, userRow())], rowCount: 1 };
    }
    return { rows: [], rowCount: 0 };
