}));
vi.mock('../services/totp', () => ({
  verifyTotpCode: vi.fn(() => state.totpValid),
  verifyBackupCode: vi.fn(async () => ({ valid: state.backupValid, index: 0 })),
  generateTotpSecret: vi.fn(() => ({ secret: 'S', otpauthUrl: 'u' })),
  generateOtpAuthUri: vi.fn(() => 'u'),
  generateBackupCodes: vi.fn(() => ['AAAAAAAA']),
  hashBackupCode: vi.fn(async (c: string) => `h:${c}`),
}));
vi.mock('../middleware/authenticate', () => {
  const gate = () => (req: any, res: any, next: () => void) => {
    const h = String(req.headers?.authorization ?? '');
    if (!h.startsWith('Bearer ') || h.length <= 'Bearer '.length) {
      res.status(401).json({ code: 'UNAUTHORIZED', message: 'Authentication required' });
      return;
