let server: Server;
let base: string;

beforeAll(async () => {
  const { mfaRoutes } = await import('../routes/mfa');
  const { errorHandler } = await import('../middleware/errorHandler');
  const app = express();
  app.use(express.json());
  app.use('/api/auth/mfa', mfaRoutes);
  app.use(errorHandler);
  server = app.listen(0, '127.0.0.1');
  await new Promise<void>((r) => server.once('listening', () => r()));
  base = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
});
afterAll(async () => { await new Promise<void>((r) => server.close(() => r())); });

beforeEach(() => {
  state.hasPassword = true; state.passwordValid = false;
  state.totpValid = false; state.backupValid = false; state.queries = [];
});

async function disable(body: Record<string, unknown>) {
  const res = await fetch(`${base}/api/auth/mfa/disable`, {
    method: 'POST',
    headers: { Authorization: 'Bearer ks732-token', 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
  return { status: res.status, body: await res.text() };
}
const disableWrites = () =>
  state.queries.filter((q) => /^\s*UPDATE\s+users/i.test(q.sql) && /mfa_enabled\s*=/i.test(q.sql));

describe('KS-732 — no path disables MFA on a bearer alone, and no account type is locked out', () => {
  it('🔴 CELL 1 — COMPATIBILITY INVARIANT: a password account with the CORRECT password and nothing else still succeeds', async () => {
    state.hasPassword = true; state.passwordValid = true;
    const r = await disable({ password: 'correct-horse' });
    expect(r.status, `a valid request today must not start failing: ${r.body}`).toBe(200);
  });

  it('🔴 CELL 2 — a password account with a WRONG password is REFUSED (this is the defect)', async () => {
    state.hasPassword = true; state.passwordValid = false;
    const r = await disable({ password: 'anything' });
    expect(r.status).not.toBe(200);
    expect(disableWrites().length, 'a refused disable must not write').toBe(0);
  });

  it('🔴 CELL 3 — a SUPPLIED totpCode is verified: correct password + wrong code is REFUSED', async () => {
    state.hasPassword = true; state.passwordValid = true; state.totpValid = false;
    const r = await disable({ password: 'correct-horse', totpCode: '000000' });
    expect(r.status, 'a wrong code must fail, not be ignored').not.toBe(200);
  });

  it('🔴 CELL 4 — a PASSWORDLESS account with a valid totpCode succeeds (not locked out)', async () => {
    state.hasPassword = false; state.totpValid = true;
    const r = await disable({ password: 'ignored-no-password-on-file', totpCode: '123456' });
    expect(r.status, `a wallet account must be able to disable MFA: ${r.body}`).toBe(200);
  });

  it('🔴 CELL 5 — a PASSWORDLESS account with a valid backupCode succeeds', async () => {
    state.hasPassword = false; state.backupValid = true;
    const r = await disable({ password: 'ignored', backupCode: 'ABCD2345' });
    expect(r.status, `backupCode must reach the handler — it cannot arrive via totpCode: ${r.body}`).toBe(200);
  });

  it('🔴 CELL 6 — a PASSWORDLESS account supplying NEITHER code is REFUSED, not quietly allowed', async () => {
    state.hasPassword = false; state.totpValid = false; state.backupValid = false;
    const r = await disable({ password: 'bearer-alone' });
    expect(r.status, 'this is the original defect wearing the new shape: a bearer alone must not disable MFA').not.toBe(200);
    expect(disableWrites().length, 'nothing may be written').toBe(0);
  });

  it('🔴 CELL 7 — CONTROL: a SUCCESSFUL disable actually WRITES mfa_enabled', async () => {
    // Without this every "succeeds" cell above is satisfied by a 200 that does
    // nothing — exactly the KS-720 defect in this ticket's clothing.
    state.hasPassword = true; state.passwordValid = true;
    await disable({ password: 'correct-horse' });
    const w = disableWrites();
    expect(w.length, `UPDATEs seen: ${state.queries.filter(q => /UPDATE/i.test(q.sql)).map(q => q.sql).join(' | ') || '(none)'}`).toBeGreaterThan(0);
    expect(w[0].params, 'mfa_enabled must be written false').toContain(false);
  });

  // ==========================================================================
  // #872 REVIEW — the cells the loose stub could not have failed
  // ==========================================================================
  it('🔴 CELL 8 — the handler asks the DATABASE for password_hash, not just the User shape', async () => {
    // Peter's blocker in one assertion. getUserById selects USER_COLS, which
    // OMITS password_hash, so `user.passwordHash` was undefined for every
    // account and the password branch was dead — while every cell above stayed
    // green, because the old stub returned the whole row whatever was selected.
    //
    // This pins the SQL rather than the outcome: an outcome assertion passes
    // again the moment someone re-points the handler at a column-less lookup
    // and the stub goes loose again.
    state.hasPassword = true; state.passwordValid = true;
    const r = await disable({ password: 'correct-horse' });
    expect(r.status, r.body).toBe(200);

    const userSelects = state.queries
      .map(q => q.sql)
      .filter(sql => /^\s*SELECT/i.test(sql) && /FROM\s+users/i.test(sql));

    expect(userSelects.length).toBeGreaterThan(0);
    expect(userSelects.some(sql => /\bpassword_hash\b/.test(sql))).toBe(true);
  });

  it('🔴 CELL 9 — CONTROL: the stub really does project, so CELL 8 is not vacuous', async () => {
    // If the stub ever stops honouring the column list, this fails and CELL 8
    // becomes meaningless without anyone noticing. A lookup that does NOT ask
    // for password_hash must NOT yield one.
    const { query } = await import('../db');
    const withHash: any = await (query as any)('SELECT id, password_hash FROM users WHERE id = $1', [USER_ID]);
    const without: any = await (query as any)('SELECT id, email FROM users WHERE id = $1', [USER_ID]);

    expect('password_hash' in withHash.rows[0]).toBe(true);
    expect('password_hash' in without.rows[0]).toBe(false);
  });

  it('🔴 CELL 10 — note 1: a WALLET account no longer has to post a dummy password', async () => {
    // The field is optional now. Omitting it entirely must still succeed for a
    // passwordless account that supplies a valid TOTP code.
    state.hasPassword = false; state.totpValid = true;
    const r = await disable({ totpCode: '123456' });
    expect(r.status, `a wallet account must not need a dummy password: ${r.body}`).toBe(200);
  });

  it('🔴 CELL 11 — and a PASSWORD account that omits it is REFUSED, not admitted', async () => {
    // The relaxation must not become a bypass: absence is a refusal in the
    // password branch, never a skipped check.
    state.hasPassword = true; state.passwordValid = true;
    const r = await disable({});
    expect(r.status, 'omitting the password must refuse, never skip the check').toBe(401);
    expect(disableWrites().length, 'a refused disable must not write').toBe(0);
  });

  it('🔴 CELL 12 — the PUBLISHED request contract matches the handler contract', async () => {
    // Two separate Zod objects declare one contract: disableSchema in
    // routes/mfa.ts and MfaDisableRequestSchema in auth.openapi.ts. They had
    // already drifted — relaxing the handler's `password` to optional left the
    // published component still emitting `required: [password]`, so the spec
    // said a field was mandatory that the code accepts as absent. Same class as
    // #805's F1: a document asserting what the code does not do.
    const specSrc = await readFile(
      new URL('../auth.openapi.ts', import.meta.url).pathname, 'utf8',
    );
    const handlerSrc = await readFile(
      new URL('../routes/mfa.ts', import.meta.url).pathname, 'utf8',
    );

    const optionalInSpec = /'MfaDisableRequest',[\s\S]{0,900}?password: z\.string\(\)\.min\(1\)\.optional\(\)/.test(specSrc);
    const optionalInHandler = /const disableSchema = z\.object\(\{[\s\S]{0,900}?password: z\.string\(\)\.min\(1\)\.optional\(\)/.test(handlerSrc);

    // CONTROL — both regexes must be able to find the field at all, or a rename
    // would make this cell pass by matching nothing on both sides.
    expect(/'MfaDisableRequest',[\s\S]{0,900}?password: z\.string\(\)/.test(specSrc)).toBe(true);
    expect(/const disableSchema = z\.object\(\{[\s\S]{0,900}?password: z\.string\(\)/.test(handlerSrc)).toBe(true);

    expect(optionalInSpec).toBe(optionalInHandler);
    expect(optionalInHandler).toBe(true);
  });

  it('🔴 CELL 13 — the 401 contract no longer says the password is never checked', async () => {
    // That sentence was TRUE before this PR and is the defect it removes.
    // Leaving it in the published contract would tell integrators the opposite
    // of what the endpoint now does.
    const specSrc = await readFile(
      new URL('../auth.openapi.ts', import.meta.url).pathname, 'utf8',
    );
    const disableBlock = specSrc.slice(specSrc.indexOf("summary: 'Disable MFA'") - 400);
    // CONTROL: the phrase is still discussed in the KS-732 note, so scope the
    // assertion to the RESPONSE description rather than the whole file.
    expect(specSrc.includes('KS-732')).toBe(true);
    expect(
      /description:\s*\n?\s*'Missing or invalid bearer token, or[\s\S]{0,200}password is never checked/.test(specSrc),
    ).toBe(false);
  });
});
